#[derive(Serialize, Deserialize, Clone)]
#[serde(tag = "state", rename_all = "snake_case")]
enum OrderState {
    AwaitingPayment,
    AwaitingStock { cid: String },
    Compensating { reason: String },
    Done,
}

fn decide(state: &OrderState, ev: &Event) -> (OrderState, Vec<Command>) {
    match (state, ev) {
        (OrderState::AwaitingPayment, Event::PaymentOk { cid }) =>
            (OrderState::AwaitingStock { cid: cid.clone() }, vec![Command::ReserveStock(cid.clone())]),
        (OrderState::AwaitingPayment, Event::PaymentTimeout { cid }) =>
            (OrderState::Compensating { reason: "timeout".into() }, vec![Command::ReleaseCredit(cid.clone())]),
        _ => (state.clone(), vec![]),        // stale or duplicate reply
    }
}

